        if (id == null || !id.matches("\\d{1,18}")) {
            throw new IllegalArgumentException("INVALID ID");
        }
        List<String> rows = query("SELECT " + COLUMNS + " FROM customer WHERE id = ?", Long.parseLong(id));
        if (rows.isEmpty()) {
            throw new IllegalArgumentException("UNKNOWN CUSTOMER: " + id);
        }
        String city = rows.get(0).split("\\|")[2];
        return query("SELECT " + COLUMNS + " FROM customer WHERE city = ? AND id <> ? ORDER BY id", city, Long.parseLong(id));
    }

